/* c-01.c —— 指针与内存：堆、栈、借用与释放
 * 编译：gcc -std=c11 -Wall -Wextra -g c-01.c -o c-01
 *   或：clang -std=c11 -Wall -Wextra -g c-01.c -o c-01
 * 可选：追加 -fsanitize=address 观察越界与 use-after-free
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int   *data;
    size_t len;
} IntVec;

/* 成功返回 0，失败返回 -1；调用方负责 vec_free */
static int vec_init(IntVec *v, size_t n)
{
    if (n > SIZE_MAX / sizeof *v->data) return -1;   /* 乘法溢出保护 */
    v->data = malloc(n * sizeof *v->data);
    if (v->data == NULL) return -1;                  /* 失败必须判空 */
    v->len = n;                                      /* 成功后才写长度 */
    for (size_t i = 0; i < n; ++i) v->data[i] = (int)(i * i);
    return 0;
}

static void vec_free(IntVec *v)
{
    free(v->data);      /* free(NULL) 是合法的空操作 */
    v->data = NULL;     /* 置空只防本结构体二次释放 */
    v->len  = 0;
}

/* 只读借用：const 说明不写调用方的内存 */
static int sum(const int *xs, size_t n)
{
    int total = 0;
    for (size_t i = 0; i < n; ++i) total += xs[i];
    return total;
}

int main(void)
{
    IntVec v = {0};                     /* 聚合初始化：data=NULL, len=0 */
    if (vec_init(&v, 5) != 0) {
        fprintf(stderr, "vec_init failed\n");
        return 1;
    }
    printf("len=%zu sum=%d\n", v.len, sum(v.data, v.len));   /* len=5 sum=30 */

    int stack_arr[5] = {1, 2, 3, 4, 5};
    printf("elems=%zu bytes=%zu\n",
           sizeof stack_arr / sizeof stack_arr[0],          /* 5 */
           sizeof stack_arr);                               /* 20（int 4 字节时） */

    const int *p = stack_arr;           /* *p 只读，p 本身可以改 */
    p += 2;                             /* 前进 2 * sizeof(int) 字节 */
    printf("p[0]=%d p[1]=%d\n", p[0], p[1]);                 /* p[0]=3 p[1]=4 */

    int *const fixed = stack_arr;       /* fixed 不能改指向，*fixed 可以改 */
    fixed[0] = 100;
    printf("stack_arr[0]=%d\n", stack_arr[0]);               /* 100 */

    vec_free(&v);
    printf("after free: len=%zu null=%d\n", v.len, v.data == NULL); /* 0 1 */
    return 0;
}

