/* c-02.c —— C 字符串：结尾符约定、边界与手动所有权
 * 编译：gcc -std=c11 -Wall -Wextra -g -fsanitize=address c-02.c -o c-02
 *   或：clang -std=c11 -Wall -Wextra -g -fsanitize=address c-02.c -o c-02
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 拼接 a + b：成功返回新字符串（调用方 free），失败返回 NULL */
static char *str_join(const char *a, const char *b)
{
    size_t na = strlen(a);
    size_t nb = strlen(b);
    if (na > SIZE_MAX - nb - 1) return NULL;   /* na + nb + 1 溢出 */
    char *out = malloc(na + nb + 1);           /* +1 给结尾符 */
    if (out == NULL) return NULL;
    memcpy(out, a, na);                        /* 不含结尾符 */
    memcpy(out + na, b, nb + 1);               /* 连结尾符一起拷 */
    return out;
}

/* 返回需要的长度（不含结尾符）；cap 不足时截断写入 */
static int format_path(char *buf, size_t cap, const char *dir, const char *file)
{
    return snprintf(buf, cap, "%s/%s", dir, file);
}

int main(void)
{
    char name[16];
    int n = snprintf(name, sizeof name, "%s", "a-very-long-user-name");
    printf("n=%d cap=%zu name=[%s] len=%zu\n", n, sizeof name, name, strlen(name));
    /* n=21 cap=16 name=[a-very-long-us] len=15：截断但一定以结尾符收尾 */

    char *s = str_join("hello, ", "world");
    if (s == NULL) return 1;
    printf("s=[%s] len=%zu\n", s, strlen(s));       /* s=[hello, world] len=12 */
    free(s);
    s = NULL;

    char small[6];
    int need = format_path(small, sizeof small, "/var/log", "app.log");
    printf("need=%d small=[%s]\n", need, small);     /* need=16 small=[/var/] */

    char big[32];
    need = format_path(big, sizeof big, "/var/log", "app.log");
    printf("need=%d big=[%s]\n", need, big);         /* need=16 big=[/var/log/app.log] */

    const char *lit = "abc";
    char arr[] = "abc";
    printf("sizeof lit=%zu sizeof arr=%zu strlen(arr)=%zu\n",
           sizeof lit, sizeof arr, strlen(arr));     /* 64 位：8 4 3 */
    return 0;
}

