// c-03.cpp —— RAII：把资源生命周期绑定到对象生命周期
// 编译：g++ -std=c++17 -Wall -Wextra -g c-03.cpp -o c-03
//   或：clang++ -std=c++17 -Wall -Wextra -g c-03.cpp -o c-03
#include <cstddef>
#include <cstdio>
#include <memory>
#include <stdexcept>
#include <utility>
#include <vector>

class Buffer {
public:
    explicit Buffer(std::size_t n) : data_(new int[n]()), n_(n) {
        std::printf("  Buffer(%zu) 构造\n", n_);
    }
    ~Buffer() {
        std::printf("  Buffer(%zu) 析构\n", n_);
        delete[] data_;
    }

    // 资源不可复制：两个对象会释放同一块内存
    Buffer(const Buffer &) = delete;
    Buffer &operator=(const Buffer &) = delete;

    // 移动 = 偷走指针，并把源对象置空（否则源对象析构时二次释放）
    Buffer(Buffer &&other) noexcept : data_(other.data_), n_(other.n_) {
        other.data_ = nullptr;
        other.n_ = 0;
    }
    Buffer &operator=(Buffer &&other) noexcept {
        if (this != &other) {            // 自赋值时先 delete 会删掉要搬的内存
            delete[] data_;
            data_ = other.data_;
            n_ = other.n_;
            other.data_ = nullptr;
            other.n_ = 0;
        }
        return *this;
    }

    int &operator[](std::size_t i) { return data_[i]; }
    std::size_t size() const { return n_; }

private:
    int *data_;
    std::size_t n_;
};

static void may_throw(bool boom) {
    Buffer b(3);                        // 无论怎么离开作用域，b 都会析构
    b[0] = 42;
    if (boom) throw std::runtime_error("boom");
    std::printf("  no throw, b[0]=%d\n", b[0]);
}

int main() {
    std::printf("1) 异常路径\n");
    try {
        may_throw(true);
    } catch (const std::exception &e) {
        std::printf("  caught: %s\n", e.what());
    }

    std::printf("2) unique_ptr 转移所有权\n");
    {
        auto p = std::make_unique<Buffer>(2);
        std::vector<std::unique_ptr<Buffer>> owners;
        owners.push_back(std::move(p));  // 转移后 p 为空
        std::printf("  p is %s, owners=%zu\n", p ? "non-null" : "null", owners.size());
    }

    std::printf("3) shared_ptr 引用计数\n");
    {
        auto sp = std::make_shared<Buffer>(1);
        std::printf("  use_count=%ld\n", static_cast<long>(sp.use_count()));
        {
            auto sp2 = sp;               // 拷贝：计数 +1
            std::printf("  use_count=%ld\n", static_cast<long>(sp.use_count()));
        }
        std::printf("  use_count=%ld\n", static_cast<long>(sp.use_count()));
    }

    std::puts("4) end of main");
    return 0;
}

