/* c-04：对齐、填充、位域与布局验证（C11）
 *
 * 编译运行：
 *   cc -std=c11 -Wall -Wextra -O2 c04.c -o c04 && ./c04
 * 说明：下面的尺寸基于 x86-64 / wasm32 的 LP64 与 ILP32 布局，
 *       只用到固定宽度整数，不含指针，所以两种平台结果一致。
 */
#include <stdalign.h>   /* alignof 宏；_Alignas 是 C11 关键字 */
#include <stddef.h>     /* offsetof */
#include <stdint.h>
#include <stdio.h>
#include <string.h>     /* memset / memcmp / memcpy */

/* 1) 直觉写法：小字段夹在大字段中间，填充最多 */
struct BadOrder {
    uint8_t  ver;
    uint32_t seq;
    uint8_t  flags;
    uint64_t ts;
};

/* 2) 按对齐值从大到小排：同样四个字段，少 8 字节 */
struct GoodOrder {
    uint64_t ts;
    uint32_t seq;
    uint8_t  ver;
    uint8_t  flags;
};

/* 3) 去掉填充：省空间，但字段未对齐 */
#pragma pack(push, 1)
struct Packed {
    uint8_t  ver;
    uint32_t seq;
    uint8_t  flags;
    uint64_t ts;
};
#pragma pack(pop)

/* 4) 缓存行隔离：两个热字段各占一条 64 字节缓存行，避免伪共享 */
struct PaddedCounters {
    _Alignas(64) uint64_t hits;
    _Alignas(64) uint64_t misses;
};

/* 5) 联合体：所有成员共享首地址，大小取最大成员 */
union Word {
    uint64_t u64;
    uint32_t u32[2];
    uint8_t  bytes[8];
};

/* 6) 编译期契约：布局一旦被改，编译就失败，而不是等线上解析错 */
_Static_assert(offsetof(struct BadOrder, seq) == 4, "seq 偏移变了，别动字段顺序");
_Static_assert(offsetof(struct BadOrder, ts) == 16, "ts 偏移变了，填充规则也变了");
_Static_assert(sizeof(struct GoodOrder) == 16, "GoodOrder 应当只占 16 字节");
_Static_assert(sizeof(struct Packed) == 14, "pack(1) 之后应当没有填充");
_Static_assert(sizeof(struct PaddedCounters) == 128, "两个字段各占一行");

/* 打印一个结构体的布局：字段名、偏移、大小 */
#define SHOW_FIELD(T, f) \
    printf("  %-6s offset=%-3zu size=%zu\n", #f, offsetof(T, f), sizeof(((T *)0)->f))

int main(void) {
    printf("BadOrder  sizeof=%zu align=%zu\n",
           sizeof(struct BadOrder), alignof(struct BadOrder));
    SHOW_FIELD(struct BadOrder, ver);
    SHOW_FIELD(struct BadOrder, seq);
    SHOW_FIELD(struct BadOrder, flags);
    SHOW_FIELD(struct BadOrder, ts);

    printf("GoodOrder sizeof=%zu align=%zu\n",
           sizeof(struct GoodOrder), alignof(struct GoodOrder));
    SHOW_FIELD(struct GoodOrder, ts);
    SHOW_FIELD(struct GoodOrder, seq);

    printf("Packed    sizeof=%zu align=%zu\n",
           sizeof(struct Packed), alignof(struct Packed));
    SHOW_FIELD(struct Packed, ts);       /* 偏移 6：未对齐 */

    printf("PaddedCounters sizeof=%zu（每字段独占 64 字节）\n",
           sizeof(struct PaddedCounters));

    /* 7) 填充字节：字段全等，memcmp 仍然不等 */
    struct BadOrder a, b;
    memset(&a, 0xAA, sizeof a);          /* 故意把填充写成 0xAA */
    memset(&b, 0x00, sizeof b);
    a.ver = b.ver = 1;
    a.seq = b.seq = 2;
    a.flags = b.flags = 3;
    a.ts = b.ts = 4;
    printf("字段全等 memcmp!=0 -> %d\n", memcmp(&a, &b, sizeof a) != 0);

    /* 8) 整体 memcpy 会连填充一起复制，所以两边填充相同时 memcmp 才为 0 */
    memcpy(&b, &a, sizeof a);
    printf("memcpy 之后 memcmp -> %d\n", memcmp(&a, &b, sizeof a));

    /* 9) 联合体：写 u64、读字节，结果依赖字节序 */
    union Word w;
    w.u64 = 0x0102030405060708ULL;
    printf("word bytes =");
    for (size_t i = 0; i < sizeof w.bytes; i++) {
        printf(" %02x", (unsigned)w.bytes[i]);
    }
    printf("（小端机器上是 08 07 06 05 04 03 02 01）\n");

    /* 10) 位域：只在本机内部使用，不要取地址、不要假设二进制形态 */
    struct Flags {
        unsigned ready : 1;
        unsigned mode  : 3;
        unsigned retry : 4;
    } fl = {0};
    fl.ready = 1;
    fl.mode  = 5;
    fl.retry = 9;
    printf("flags sizeof=%zu ready=%u mode=%u retry=%u\n",
           sizeof(struct Flags), fl.ready, fl.mode, fl.retry);
    return 0;
}

