/* c-05：一个翻译单元里，把「预处理 / 编译 / 汇编 / 链接」四层的痕迹都摆出来
 *
 * 构建与观察（单文件版本，可直接编译运行）：
 *   cc -std=c11 -Wall -Wextra -O0 -g c05.c -o c05 && ./c05
 * 逐阶段看产物：
 *   cc -std=c11 -E c05.c > c05.i    # 预处理：宏已展开、注释已删除、头文件已插入
 *   cc -std=c11 -S c05.c -o c05.s   # 编译：得到汇编
 *   cc -std=c11 -c c05.c -o c05.o   # 汇编：得到可重定位目标文件
 *   nm c05.o                        # 符号表：T 全局代码 / t 内部代码 / D 已初始化数据
 *                                   #         B 未初始化数据 / U 未定义（等链接器补）
 *   cc c05.o -o c05                 # 链接：解析 U，拼出可执行文件
 *
 * 注意：-O2 下 clamp 与 stats_avg 会被内联，nm 里连符号都不剩，
 *       这也是「优化后调试困难」的一个具体表现。
 */
#include <stdint.h>
#include <stdio.h>

/* ---------- 1) 模拟一个 header 的全部内容：类型 + 宏 + extern 声明 + inline ---------- */
#ifndef C05_STATS_H
#define C05_STATS_H   /* 头文件保护：防同一翻译单元内重复展开，防不了跨 TU 重复定义 */

#define STATS_MAX_SAMPLES 8   /* 宏：预处理期替换，没有类型检查，也没有地址 */

typedef struct {              /* 类型定义不产生符号，放头文件是安全的 */
    uint32_t count;
    int64_t  sum;
} Stats;

extern int g_verbose;         /* 声明：只告诉编译器「有这么个对象」，不分配存储 */

static inline int64_t stats_avg(const Stats *s) {   /* static：内部链接，每个 TU 一份 */
    return s->count ? s->sum / (int64_t)s->count : 0;
}
#endif /* C05_STATS_H */

/* ---------- 2) 定义：真正分配存储的地方 ---------- */
int g_verbose = 0;            /* 删掉这行，g_verbose 就只剩 U，链接时报 undefined reference */

/* ---------- 3) static：内部链接，别的 .o 看不到，也不会和别人的同名函数冲突 ---------- */
static int64_t clamp(int64_t v, int64_t lo, int64_t hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

/* ---------- 4) 宏 vs inline 函数：参数求值次数不一样 ---------- */
#define SQUARE(x) ((x) * (x))          /* 不检查类型，参数写几次就求值几次 */

static int64_t square(int64_t x) { return x * x; }   /* 参数只求值一次，有类型 */

static int64_t probe(void) {           /* 用打印把「被调用几次」变成可见事实 */
    printf("[probe]");
    return 3;
}

/* 编译期就能确定的事，别留到运行期：布局和语言版本都可以在这里钉死 */
_Static_assert(sizeof(Stats) == 16, "Stats 的布局变了，跨文件读写会错位");

int main(void) {
    Stats s = {0, 0};
    int i = 0;

    for (i = 0; i < STATS_MAX_SAMPLES; i++) {
        s.count++;
        s.sum += i;
    }
    printf("count=%u sum=%lld avg=%lld\n",
           s.count, (long long)s.sum, (long long)stats_avg(&s));

    printf("SQUARE(probe())=%lld\n", (long long)SQUARE(probe()));  /* [probe][probe]9 */
    printf("square(probe())=%lld\n", (long long)square(probe()));   /* [probe]9 */

    g_verbose = 1;
    if (g_verbose) {
        printf("clamp(-5, 0, 10)=%lld\n", (long long)clamp(-5, 0, 10));
    }

    printf("sizeof(Stats)=%zu\n", sizeof(Stats));
    printf("__STDC_VERSION__=%ld\n", (long)__STDC_VERSION__);  /* -std=c11 下为 201112 */
    return 0;
}

