// c-06：模板实例化、容器复杂度与迭代器失效（C++17）
// 编译：g++ -std=c++17 -Wall -Wextra -O2 c06.cpp -o c06
#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <type_traits>
#include <unordered_map>
#include <vector>

// 1) 函数模板：不是函数，是生成函数的规则；T 由调用点推导
template <typename T>
T clamp_value(T v, T lo, T hi) {
    return v < lo ? lo : (v > hi ? hi : v);
}

// 2) 类模板：主模板 + 全特化 + 偏特化
template <typename T>
struct TypeName {
    static const char *get() { return "other"; }
};

template <>
struct TypeName<int> {                 // 全特化：T 必须精确是 int
    static const char *get() { return "int"; }
};

template <typename T>
struct TypeName<T *> {                 // 偏特化：只固定「是指针」这一件事
    static const char *get() { return "pointer"; }
};

// 3) if constexpr（C++17）：编译期分支，没走到的分支不会被实例化
template <typename T>
std::string describe(const T &v) {
    if constexpr (std::is_integral<T>::value) {
        return "integral:" + std::to_string(v);
    } else {
        return std::string("other:") + v;   // T 非整数时才实例化这一支
    }
}

int main() {
    // 4) 两次调用生成两份 clamp_value，实例化发生在编译期
    std::cout << clamp_value(5, 1, 3) << ' ' << clamp_value(2.5, 1.0, 3.0) << '\n';

    std::cout << TypeName<int>::get() << ' ' << TypeName<int *>::get() << ' '
              << TypeName<double>::get() << '\n';

    std::cout << describe(42) << ' ' << describe(std::string("abc")) << '\n';

    // 5) vector：连续内存，push_back 超过容量就搬家，之前的指针全部悬空
    std::vector<int> v;
    v.reserve(4);
    for (int i = 0; i < 4; ++i) v.push_back(i);
    const int *p = v.data();
    v.push_back(4);                    // 第 5 个元素触发扩容（4 -> 8）
    std::cout << "size=" << v.size() << " cap=" << v.capacity()
              << " moved=" << (v.data() != p) << '\n';   // moved=1：p 已悬空

    // 6) 先按最终规模 reserve，指针才稳定
    std::vector<int> w;
    w.reserve(8);
    for (int i = 0; i < 5; ++i) w.push_back(i);
    int *q = w.data();
    w.push_back(5);                    // 容量还够，不搬家
    std::cout << "same=" << (w.data() == q) << " cap=" << w.capacity() << '\n';

    // 7) 删除元素用 erase-remove（C++20 起可以直接 std::erase_if）
    w.erase(std::remove_if(w.begin(), w.end(), [](int x) { return x % 2 == 0; }),
            w.end());
    std::cout << "after erase:";
    for (int x : w) std::cout << ' ' << x;
    std::cout << '\n';

    // 8) map 有序、O(log n)；unordered_map 平均 O(1)，rehash 不失效引用
    std::map<std::string, int> ordered;
    std::unordered_map<std::string, int> hashed;
    ordered["a"] = 1;
    hashed["a"] = 1;
    const int &ref = hashed["a"];
    for (int i = 0; i < 1000; ++i) hashed["k" + std::to_string(i)] = i;
    std::cout << "hashed size=" << hashed.size() << " ref_ok=" << (ref == 1) << '\n';

    // 9) operator[] 会插入默认值：查询请用 find / count / contains
    std::cout << "find b: " << (ordered.find("b") == ordered.end() ? "缺" : "有");
    ordered["b"];                      // 悄悄插入 {b, 0}
    std::cout << " 之后 size=" << ordered.size() << '\n';

    // 10) 有序容器才能做范围查询：unordered_map 只有等值查找
    ordered["c"] = 3;
    const auto it = ordered.lower_bound("b");
    std::cout << "lower_bound(b)=" << (it != ordered.end() ? it->first : std::string("none"))
              << '\n';
    return 0;
}

