/* c07_demo.c — 购物车的三处内存 bug：UAF、越界隐患、泄漏
 * 构建（Linux / macOS，clang 或 gcc）：
 *   cc -std=c11 -g -O1 -fsanitize=address,undefined -fno-omit-frame-pointer c07_demo.c -o c07_asan
 *   cc -std=c11 -g -O0 c07_demo.c -o c07_plain
 * 运行：
 *   ./c07_plain   # 很可能打印 "last was pear" 并以 0 退出：看不出问题
 *   ./c07_asan    # 打印 heap-use-after-free 报告，退出码 1
 * Windows 下用 clang（MSVC 的 ASan 支持有限）：
 *   clang -std=c11 -g -O1 -fsanitize=address c07_demo.c -o c07_asan.exe
 */
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int   weight;
} item;

typedef struct {
    item  *data;
    size_t len;
    size_t cap;
} cart;

static int cart_push(cart *c, const char *name, int weight)
{
    if (c->len == c->cap) {
        size_t cap = c->cap ? c->cap * 2 : 4;
        item *grown = realloc(c->data, cap * sizeof *grown);
        if (!grown) {
            return -1;                       /* 失败时 c->data 仍有效，不会泄漏 */
        }
        c->data = grown;
        c->cap  = cap;
    }

    size_t n = strlen(name);
    char *copy = malloc(n + 1);              /* +1 给结尾的 '\0'，漏了就多写一字节 */
    if (!copy) {
        return -1;
    }
    memcpy(copy, name, n + 1);

    c->data[c->len].name   = copy;
    c->data[c->len].weight = weight;
    c->len++;
    return 0;
}

/* 返回内部指针（borrowed）：生命周期跟着 cart，调用方不得保存、不得 free */
static const char *cart_last_name(const cart *c)
{
    return c->len ? c->data[c->len - 1].name : NULL;
}

static void cart_drop_last(cart *c)
{
    if (c->len == 0) {
        return;                              /* 没有这行，--c->len 会下溢成 SIZE_MAX */
    }
    item last = c->data[--c->len];
    printf("drop %s (%d g)\n", last.name, last.weight);
    free(last.name);
}

int main(void)
{
    cart c = {0};
    if (cart_push(&c, "apple", 120) != 0 || cart_push(&c, "pear", 200) != 0) {
        free(c.data);
        return 1;
    }

    const char *name = cart_last_name(&c);   /* 借到 pear 那块堆内存的地址 */
    cart_drop_last(&c);                      /* 这里把它 free 了 */
    printf("last was %s\n", name);           /* UAF：ASan 在 strlen 内部报错 */

    free(c.data);                            /* 只释放数组本体，name 全部泄漏 */
    return 0;
}

