// c08_demo.cpp — 移动语义计数 + vector/list 遍历对比（C++17）
// 构建：
//   c++ -std=c++17 -O2 -DNDEBUG c08_demo.cpp -o c08_demo
//   c++ -std=c++17 -O0 c08_demo.cpp -o c08_demo_dbg
// 运行：./c08_demo
// 预期（GCC、Clang、MSVC 在 -O0 下也会做 NRVO；标准不强制，若你的编译器不做则 copies=1）：
//   copies=0 moves=1
//   sizes=1024 1024 1024
//   耗时随机器变化，vector 通常比 list 快 5 到 15 倍；ratio 那一行会浮动
#include <chrono>
#include <cstddef>
#include <cstdio>
#include <list>
#include <utility>
#include <vector>

struct Buffer {
    static int copies;
    static int moves;

    std::vector<int> data;

    explicit Buffer(std::size_t n) : data(n, 7) {}
    Buffer(const Buffer &o) : data(o.data) { ++copies; }
    Buffer(Buffer &&o) noexcept : data(std::move(o.data)) { ++moves; }
    Buffer &operator=(const Buffer &) = default;
    Buffer &operator=(Buffer &&) noexcept = default;
};

int Buffer::copies = 0;
int Buffer::moves  = 0;

Buffer make_nrvo(void) { Buffer b(1024); return b; }             // NRVO：0 拷贝 0 移动
Buffer make_move(void) { Buffer b(1024); return std::move(b); }  // 禁用 NRVO：1 次移动
Buffer make_prvalue(void) { return Buffer(1024); }               // C++17 强制消除：0 次

template <class Seq>
long long sum(const Seq &s)
{
    long long acc = 0;
    for (const auto &v : s) {
        acc += v;
    }
    return acc;
}

int main(void)
{
    Buffer a = make_nrvo();
    Buffer b = make_move();
    Buffer c = make_prvalue();
    std::printf("copies=%d moves=%d\n", Buffer::copies, Buffer::moves);
    std::printf("sizes=%zu %zu %zu\n", a.data.size(), b.data.size(), c.data.size());

    constexpr std::size_t N = 200000;
    std::vector<int> vec(N);
    for (std::size_t i = 0; i < N; ++i) {
        vec[i] = static_cast<int>(i);
    }
    std::list<int> lst(vec.begin(), vec.end());  // 计时之外：20 万次节点分配

    const auto t0 = std::chrono::steady_clock::now();
    volatile long long s1 = sum(vec);            // volatile：防止整个循环被优化掉
    const auto t1 = std::chrono::steady_clock::now();
    volatile long long s2 = sum(lst);
    const auto t2 = std::chrono::steady_clock::now();

    auto us = [](std::chrono::steady_clock::duration d) {
        return std::chrono::duration<double, std::micro>(d).count();
    };
    std::printf("vector: %.1f us (sum=%lld)\n", us(t1 - t0), static_cast<long long>(s1));
    std::printf("list:   %.1f us (sum=%lld)\n", us(t2 - t1), static_cast<long long>(s2));
    std::printf("ratio:  %.1fx\n", us(t2 - t1) / us(t1 - t0));
    return 0;
}

