# ============================================================
cmake_minimum_required(VERSION 3.20)
project(cart LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(CMAKE_CXX_EXTENSIONS OFF)

add_library(cart src/cart.cpp)
target_include_directories(cart PUBLIC include PRIVATE src)
target_compile_options(cart PRIVATE
    $<$<CXX_COMPILER_ID:MSVC>:/W4>
    $<$<CXX_COMPILER_ID:MSVC>:/permissive->
    $<$<NOT:$<CXX_COMPILER_ID:MSVC>>:-Wall>
    $<$<NOT:$<CXX_COMPILER_ID:MSVC>>:-Wextra>
    $<$<NOT:$<CXX_COMPILER_ID:MSVC>>:-Wpedantic>)

include(CTest)
if(BUILD_TESTING)
    include(FetchContent)
    FetchContent_Declare(Catch2
        GIT_REPOSITORY https://github.com/catchorg/Catch2.git
        GIT_TAG v3.16.1)
    FetchContent_MakeAvailable(Catch2)

    add_executable(cart_tests tests/test_cart.cpp)
    target_link_libraries(cart_tests PRIVATE cart Catch2::Catch2WithMain)
    add_test(NAME cart COMMAND cart_tests)
endif()

# ============================================================
# include/cart.hpp
# ============================================================
#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace cart {

struct Item {
    std::int64_t price_cents;
    int qty;
};

class Cart {
public:
    void add(Item it);
    void clear() noexcept;
    std::size_t size() const noexcept;
    std::int64_t total_cents() const noexcept;

private:
    std::vector<Item> items_;
};

}  // namespace cart

# ============================================================
# src/cart.cpp
# ============================================================
#include "cart.hpp"

namespace cart {

void Cart::add(Item it) { items_.push_back(it); }

void Cart::clear() noexcept { items_.clear(); }

std::size_t Cart::size() const noexcept { return items_.size(); }

std::int64_t Cart::total_cents() const noexcept
{
    std::int64_t sum = 0;
    for (const auto &it : items_) {
        // 先转 64 位再乘：price_cents 已经是 int64，qty 是 int，不会溢出
        sum += it.price_cents * static_cast<std::int64_t>(it.qty);
    }
    return sum;
}

}  // namespace cart

# ============================================================
# tests/test_cart.cpp
# ============================================================
#include <catch2/catch_test_macros.hpp>

#include "cart.hpp"   // 能直接 include，靠的是 cart 的 PUBLIC include

TEST_CASE("空购物车总价为 0", "[cart]")
{
    cart::Cart c;
    REQUIRE(c.size() == 0);
    REQUIRE(c.total_cents() == 0);
}

TEST_CASE("金额乘以数量后相加", "[cart]")
{
    cart::Cart c;
    c.add({250, 2});
    c.add({100, 3});
    REQUIRE(c.size() == 2);
    REQUIRE(c.total_cents() == 800);
}

TEST_CASE("clear 之后归零", "[cart]")
{
    cart::Cart c;
    c.add({999, 1});
    c.clear();
    REQUIRE(c.size() == 0);
    REQUIRE(c.total_cents() == 0);
}

