// abi.cpp —— 稳定 ABI 边界：不透明句柄 + C 接口 + 版本化结构体
// 可执行版：g++ -std=c++17 -O2 abi.cpp -o abi
// 动态库版：g++ -std=c++17 -O2 -fPIC -shared -fvisibility=hidden -DNOTE_NO_MAIN abi.cpp -o libnote.so.1
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <new>
#include <string>
#include <vector>

#if defined(_WIN32)
#  define NOTE_API __declspec(dllexport)
#else
#  define NOTE_API __attribute__((visibility("default")))
#endif

#define NOTE_ABI_VERSION 1u

extern "C" {
struct note_ctx;                  /* 不透明句柄：调用方只能持有指针 */

NOTE_API struct note_ctx *note_open(int cap);
NOTE_API void note_close(struct note_ctx *ctx);
NOTE_API int note_push(struct note_ctx *ctx, const char *s);
NOTE_API std::size_t note_size(const struct note_ctx *ctx);
NOTE_API const char *note_version(void);
NOTE_API std::size_t note_stats(const struct note_ctx *ctx, void *out, std::size_t out_size);
}

/* 布局本身就是 ABI 的一部分，用编译期断言钉住 */
struct note_stats_v1 {
    std::uint32_t struct_size;    /* 调用方声明的长度，被调方按它裁剪写入 */
    std::uint32_t abi_version;
    std::uint64_t bytes;          /* 所有字符串内容的总字节数 */
};
static_assert(sizeof(note_stats_v1) == 16, "layout is part of the ABI");

/* 真实布局只存在于实现里：加字段不会影响任何已编译的客户端 */
struct note_ctx {
    explicit note_ctx(int c) : cap(c) {}
    std::vector<std::string> items;   /* 容器绝不跨边界 */
    int cap;
};

extern "C" note_ctx *note_open(int cap)
{
    if (cap <= 0) return nullptr;
    /* 失败返回空指针，而不是让 bad_alloc 穿过 C 边界 */
    return new (std::nothrow) note_ctx(cap);
}

extern "C" void note_close(note_ctx *ctx)
{
    delete ctx;                   /* delete nullptr 是合法的空操作 */
}

extern "C" int note_push(note_ctx *ctx, const char *s)
{
    if (ctx == nullptr || s == nullptr) return -1;
    if (ctx->items.size() >= static_cast<std::size_t>(ctx->cap)) return -2;   /* 满 */
    ctx->items.emplace_back(s);
    return 0;
}

extern "C" std::size_t note_size(const note_ctx *ctx)
{
    return ctx != nullptr ? ctx->items.size() : 0;   /* 边界函数不信任调用方 */
}

extern "C" const char *note_version(void)
{
    return "1.0.0";               /* 返回静态字符串，所有权不转移 */
}

extern "C" std::size_t note_stats(const note_ctx *ctx, void *out, std::size_t out_size)
{
    if (out == nullptr || out_size < 8) return 0;   /* 长度不够就干脆不写 */

    note_stats_v1 buf{};
    buf.struct_size = static_cast<std::uint32_t>(sizeof(note_stats_v1));
    buf.abi_version = NOTE_ABI_VERSION;
    if (ctx != nullptr)
        for (const auto &s : ctx->items) buf.bytes += s.size();

    const std::size_t n = out_size < sizeof buf ? out_size : sizeof buf;
    std::memcpy(out, &buf, n);     /* 只写调用方声明的长度，老客户端读到前缀 */
    return n;
}

#ifndef NOTE_NO_MAIN
int main(void)
{
    note_ctx *ctx = note_open(4);
    if (ctx == nullptr) return 1;

    std::printf("version=%s abi=%u\n", note_version(), NOTE_ABI_VERSION);  /* version=1.0.0 abi=1 */

    const int r1 = note_push(ctx, "ab");
    const int r2 = note_push(ctx, "cde");
    std::printf("push=%d,%d size=%zu\n", r1, r2, note_size(ctx));         /* push=0,0 size=2 */

    note_stats_v1 st{};
    std::size_t n = note_stats(ctx, &st, sizeof st);
    std::printf("written=%zu struct_size=%u version=%u bytes=%llu\n",
                n, st.struct_size, st.abi_version,
                static_cast<unsigned long long>(st.bytes));
    /* written=16 struct_size=16 version=1 bytes=5 */

    /* 模拟只认识前 8 字节的旧客户端：多出来的字段被安全截断 */
    struct { std::uint32_t struct_size; std::uint32_t abi_version; } old_client{};
    n = note_stats(ctx, &old_client, sizeof old_client);
    std::printf("old written=%zu struct_size=%u version=%u\n",
                n, old_client.struct_size, old_client.abi_version);
    /* old written=8 struct_size=16 version=1 */

    note_close(ctx);
    return 0;
}
#endif
